.stats-grid { display: grid; gap: .8rem; }
.stat-item strong { font-family: 'Space Grotesk'; font-size: clamp(1.4rem, 3vw, 2rem); display:block; }
.stat-item span { font-size: .95rem; opacity: .9; }

.pricing-grid { display: grid; gap: 1rem; }
.price-card { position: relative; }
.price-card.recommended { border-color: color-mix(in oklab, var(--accent) 55%, var(--border)); box-shadow: 0 12px 24px color-mix(in oklab, var(--accent) 18%, transparent); }
