.toggle-wrap {
  display: inline-flex; border: 1px solid var(--border); border-radius: 12px;
  background: var(--surface);
}
.toggle-wrap button {
  border: 0; background: transparent; padding: .65rem .95rem; cursor: pointer; font-weight: 700;
  color: var(--text-muted);
}
